        ds = sorted(strokes)
        vals = [next(iter(strokes[d])) for d in ds]
        # Keep the order of the encoded diagonal strokes, repeating it.
        seq = []
        for v in vals:
            if v not in seq:
                seq.append(v)
        # Preserve repeated colors when they encode successive positions.
        if len(vals) > 1 and len(set(vals)) > 1:
            seq = vals
        base = ds[0]
        return [[seq[(c-r-base) % len(seq)] for c in range(w)] for r in range(h)]

    return [row[:] for row in grid]
