def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each long down-right diagonal is a color stripe, indexed by c-r.
    # Read their colors and offsets, then extend the repeating sequence.
    stripes = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                stripes.setdefault(c - r, []).append(v)

    # Determine the smallest periodic diagonal pattern consistent with all
    # observed cells.
    for period in range(1, max(h, w) + 1):
        residues = {}
        valid = True
        for d, vals in stripes.items():
            for v in vals:
                k = d % period
                if k in residues and residues[k] != v:
                    valid = False
                    break
                residues[k] = v
            if not valid:
                break
        if valid and len(residues) == period:
            break

    # Fill any unobserved residues by extending the observed stripe colors.
    if not stripes:
        return [[0] * w for _ in range(h)]
    ds = sorted(stripes)
    for k in range(period):
        if k not in residues:
            nearest = min(ds, key=lambda d: min((d-k) % period, (k-d) % period))
            residues[k] = stripes[nearest][0]

    return [[residues[(c-r) % period] for c in range(w)] for r in range(h)]
